const s=(title,paragraphs)=>({title,paragraphs});
export const wangBranches={
discern:{name:'识局',parent:'strategy',thesis:'看现实 · 抓本质 · 推未来',question:'我看到的是局面本身，还是一个不断被自己验证的故事？',definition:['识局，是以需要解决的现实问题为起点，辨认事实与解释、结构与关键张力，并推演不同条件下的演化可能。它为战略提供可以被检验的认识，而不是为既定愿望寻找证明。'],sections:[
s('看现实：沉得进，也跳得出',['沉得进，是接近现场、使用者与承担后果的人，了解报表之外的信息；跳得出，是把局部经验放回整体，分清谁提供了什么信息、哪些声音长期缺席。','先列发生的事，再列不同解释与尚未知晓的部分。愿望可能使人忽略困难，恐惧也可能使人夸大威胁；识局要让两者都成为被观察的因素。']),
s('抓本质：矛盾、变量与要素不能混同',['主要矛盾，是当前阶段对局面走向起支配作用的关键张力。服务扩张中，需求增长与承接能力不足之间的冲突，可能比表面上的宣传不足更接近核心。','核心变量，是影响变化的重要因素，例如需求量、处理能力、交接耗时与信任；核心要素，是参与构成局面的主体、资源和结构，例如使用者、一线人员、信息平台与权限关系。变量描述变化，要素说明构成，矛盾指出关系中的关键张力。']),
s('推未来：让多个可能进入判断',['写出关键条件延续、改善或恶化时，局面可能怎样演化；同时考虑其他主体会怎样回应自己的行动。单一情景可以帮助准备，却不应被当成命运。','每种判断要说明所依赖的假设与需要观察的信号。识局的价值不在于永远预测正确，而在于错误出现时能够及时知道自己为什么需要更新。'])],questions:[
['怎样知道抓住了本质，而非换了一个故事？',['检验解释能否连接不同现象、提出可观察的变化，并经得起反例。如果它只能在结果出现后解释一切，却永远不能被事实否定，就难以指导取舍。','找一个最不符合当前解释的情境，核实是否遗漏了条件。关键张力也可能随阶段改变，没有一个词能永久统领所有局面。']],
['主要矛盾是不是唯一原因？',['不是。支配作用不表示其他因素不存在，也不保证改变一处就解决全部问题。它帮助决定优先级，但必须同时识别不能被破坏的基本条件。','将复杂关系压成一个口号，可能使人看漏不同人承担的代价。识局需要简化以便行动，也需要知道简化省略了什么。']],
['信息很多，何时停止分析？',['先问哪些新信息真正可能改变决定。与当前取舍无关的细节，可以另行积累；对高风险且不可逆的未知，则应更谨慎。','设定判断时点，把剩余不确定性带入试行与复查。识局服务决断，不以无限研究替代承担。']]
],practice:['围绕一个问题，分别收集现场、决策者与受影响者的描述。','写出主要矛盾、三个核心变量与关键要素，不用同一词替代三种分析。','为两种不同的未来情境标明假设、观察信号和可能改变的决定。'],case:['服务组织发现投诉集中在交付交接，而非作品质量；河谷城发现现有风险地图缺少部分居民经验。两者都要让遗漏的信息改变整体判断。'],sources:['oldPowers']},
breakthrough:{name:'破局',parent:'strategy',thesis:'找杠杆 · 聚力量 · 击单点',question:'什么变化足以使局面松动，又需要哪些条件来承接？',definition:['破局，是在理解关键约束后，将相称力量集中到能够改变关系的作用点，使僵局出现可验证的转变。它不是用更大的声势重复已经失效的方法。'],sections:[
s('找杠杆：从症状走向作用关系',['反复交付延误，可能因为缺人，也可能因为目标持续变动、审批阻塞或信息断裂。杠杆不是最显眼的问题，而是改变后能牵动其他条件的作用点。','可以提出“如果改变这一处，会通过什么关系带来哪些变化”。说清传递路径，才能检验所谓突破是否真的发生。']),
s('聚力量：把资源与愿意参与的人组织起来',['一个好想法不会自动形成改变。需要明确不同参与者的贡献、风险、收益与承诺，安排信息与资源，处理彼此之间的信任与分工。','反对者未必都不愿进步。有人承受过渡成本，有人担心失去正当利益，也有人维护不当优势。分别理解，才能选择协商、过渡支持、制度调整或必要竞争。']),
s('击单点：集中突破，也保护整体',['有限资源应投入足以产生实质影响的关键处，而非平均摊薄。突破范围、持续时间与判断标准应当清楚，避免一边集中，一边不断扩大目标。','集中不等于抽空所有后备能力。突破之后要有人接住新增任务、维护新规则与继续学习，否则一次高峰会很快回落成原来的限制。'])],questions:[
['杠杆与布局中的枢纽有何不同？',['杠杆强调改变局面的作用点；枢纽强调长期网络里的关键连接、协调或配置位置。修改一条审批规则可能是杠杆，形成跨部门信息平台可能使你进入枢纽。','同一个对象有时兼具两种作用，区别来自所分析的问题，而非要求事物只能属于一个类别。']],
['关键一击需要孤注一掷吗？',['不必。需要的是投入足够，风险相称，维持基本运行的条件没有被破坏。失败后仍能保护受影响者、继续承担责任，是判断的一部分。','预先明确停止条件，不会削弱认真投入；它使集中与失控有所区别。']],
['突破不了，是否说明方向错了？',['可能是因果假设错误，也可能是投入不足、协作失效或窗口尚未出现。分别检查，不用“还不够相信”包办解释。','如果目的仍有价值，却始终被某个载体限制，可以重新设计实现方式。忠于价值不必等于忠于最初方案。']]
],practice:['画出一个关键约束怎样限制其他努力，写出可被检验的作用路径。','明确参与者、资源、风险和承诺，选择一个足以产生影响的突破范围。','同时安排承接、停止条件与复查，避免只宣布一次胜利。'],case:['服务组织先集中修复一处交接，而不是同时重建所有部门；河谷城先打通跨区域预警的信息阻塞，再由常设机制承接。突破应使共同能力增长。'],sources:['oldPowers']},
layout:{name:'布局',parent:'strategy',thesis:'布先手 · 据枢纽 · 留自由',question:'让未来到来时，我已经具备哪些能够继续创造的条件？',definition:['布局，是从愿意参与的未来反观当下，提前形成能力、位置、资源与关系结构，改变进入下一局时的初始条件。它扩大未来的选择空间，也使值得创造的可能更容易发生。','破局面对已经形成的局，寻找改变其走向的作用点；布局面对尚未充分形成的局，提前培育能够进入并塑造它的条件。二者常常同时进行。'],sections:[
s('布先手：让时间成为条件的一部分',['能力、信任、知识与长期关系，往往不能在需要时立即购买。提前做这些事，是承认成长有节律，而非相信未来已被精确预定。','先手的价值不只在比别人早，更在积累是否真正通向有用的能力。过早投入一个缺乏根据的方向，也可能只是更早被锁住。']),
s('据枢纽：让结构放大贡献',['枢纽可以连接信息、人才、资源或不同群体，使有限力量产生更广泛的协作效果。这个位置需要以可靠贡献维持，而不只是依靠别人无法绕开的障碍。','要检验枢纽是在减少摩擦、增加价值，还是在制造人为依赖。王道中的布局应当允许共同能力成长，不能以压制他人选择来维持永久中心。']),
s('留自由：认真下注，也保留再次选择',['时间、资源和关系上的余地，使人能在条件变化时调整。兼容不同情境的能力与可分阶段投入的安排，能够减少对单一未来的过度依赖。','留自由也有代价。应当区分必要缓冲与回避承诺，不以保留所有可能为由拒绝形成任何真实积累。']),
s('从预备未来，到参与创造未来',['预备未来，是形成可能需要的条件；进入未来的关键位置，使这些条件能够连接更大的力量；参与创造未来，则是通过行动改变哪些可能更容易发生。','这三个观察角度延续旧文的“预备、占据、创造”，但不构成对未来的所有权。布局的最高成果，是增强未来的创造能力，而非提前消灭未来的自由。'])],questions:[
['看不准未来，怎样开始？',['从多种情境都需要的基础能力开始，同时以有限探索了解不确定方向。不同投入可以有不同的承诺程度，不必一次决定全部资源的归属。','写出哪些条件相对稳定，哪些判断高度不确定，哪些信号会使你加码、转向或退出。']],
['怎样使用“看十年、想三年、干一年”？',['把它当作长、中、短不同尺度的思考提醒，而非所有事情都适用的固定周期。长期问趋势与价值，中期问关键能力，近期问能采取的行动与反馈。','时间长度要随领域和任务调整。每个尺度都需要可修正的假设，长远愿景不能使近期失误失去检验。']],
['愿景、行动、反馈如何进入布局？',['愿景说明值得创造什么；行动使一个假设接触现实；反馈检查形成了何种能力、关系与位置。即使暂时没有显眼收益，也可以回看这些条件是否更可用。','若所谓长期投入始终无法说明积累了什么，就需要重新检视。长期不是免于评价的理由。']],
['怎样防止布局变成控制一切？',['把对其他主体的尊重写进安排：清楚的规则、对等的信息、合理的退出与协商空间。合作需要别人愿意加入，而非把所有未来都锁进自己的剧本。','据枢纽带来的权力也应接受责任与监督。这使布局继续通向系统、成人与无执。']]
],practice:['写下一个愿意参与的未来，列出必须提前积累的条件。','辨认一个能够提供真实价值的连接位置，而非只寻找控制关口。','安排近期行动与回看时点，写出哪些证据会使自己调整投入。'],case:['服务组织积累训练体系与合作关系，为不同发展路径保留基础；河谷城建设兼容多种风险情景的预警与维护能力，不把全城的资源锁定在单一预测。'],sources:['oldPowers','oldWays']},
build:{name:'建构',parent:'system',thesis:'让使命成为可运行、可接续的关系与条件。',question:'这件有价值的事，怎样不再每次都依赖临时救火？',definition:['建构，是从真实任务出发，形成目标、角色、权限、责任、资源、信息与反馈之间的关系，使不同主体可以可靠地共同工作。系统不是文件的总和，而是这些关系实际怎样运行。'],sections:[
s('先明确价值，再安排结构',['组织图不能替代共同目的。先问为谁解决什么问题、怎样判断价值，再确定需要哪些贡献。角色由任务关系形成，资源让职责可以履行。','一项责任至少需要清楚的目标、必要信息、相应权限与求助方式。缺少其中的重要条件，就容易靠额外的人情和加班维持。']),
s('规则与激励，共同决定实际行为',['规则说明应该怎样做，激励告诉人什么会被奖励，文化表现为日常行为真正受到怎样的回应。若三者相互冲突，口号通常无法改变实际取舍。','监督需要发现异常，也需要有能力推动修复。只有检查没有纠偏，成员可能学会完成检查材料，而不是改善结果。']),
s('把熟练者的判断变成可以接续的认识',['关键经验往往藏在直觉里。记录为何这样做、什么情况例外、看到什么信号应该改变，会比只列动作更能帮助新人理解。','通过训练、共同复盘与实际使用来检验这些材料。建构的成果不是写了多少制度，而是别人在新情况中是否更能可靠地判断。'])],questions:[
['小团队是否只要信任，不必规则？',['信任有价值，但记忆不同、时间紧张与角色变化仍会发生。简短的职责、决定方式与回看安排，能减少不必要的误会。','形式可以轻，关键关系不能长期模糊。规则应当帮助信任，而非用繁复程序代替它。']],
['优秀的人组成团队，为什么仍会失灵？',['不同人的努力可能被结构引向相反方向。局部指标、信息壁垒或责任与权限脱节，会使每个人完成自己的任务，却无人维护整体价值。','先观察事情如何流动，再评价个人表现。不能用换人解决每一个结构问题。']],
['怎样防止流程变成形式？',['让实际使用者说明哪一步解决什么问题，观察完成流程后关键风险是否仍然存在。无效或代价过大的步骤应当可以调整。','规则要保留目的、解释与例外处理的路径。否则人们只能遵守动作，无法面对变化。']]
],practice:['选一项反复发生的任务，记录从需求到结果的全部交接。','标出责任与权限不匹配、信息断裂或激励冲突的位置。','先修复最小的一个关系，再由使用者回看是否减少了真实摩擦。'],case:['服务组织把承诺、交付与支持接成完整链条；河谷城把预警、决策、资源调度与居民反馈明确连接。各环节的努力由此有机会形成整体能力。'],sources:['oldPowers']},
collaborate:{name:'协同',parent:'system',thesis:'保持独立判断，使不同主体的力量能够相互接续。',question:'我们各自完成的事，是否真的共同完成了那件重要的事？',definition:['协同，是在共同目标下组织不同贡献，处理信息、利益、信任与协调成本，使差异能够形成集体行动能力。它不等于把优秀的人聚在一起，也不要求所有人持有同一种意见。'],sections:[
s('局部努力，为什么不一定带来整体改善',['一个部门提高速度，可能把错误与成本推给后续环节；另一个部门降低支出，可能损害使用者的长期体验。局部成功必须放进完整价值路径里理解。','让前后环节共同回看最终结果，把维护、支持与协调的贡献变得可见，才能改变各自最优却整体失灵的局面。']),
s('连接需要目标、接口与分歧处理',['共同目标提供方向，清楚接口说明谁在何时需要什么，分歧处理使不同判断能够形成可执行的决定。没有这些条件，会议增加也不一定带来协作。','信息不对称并非总是故意隐瞒，有时来自语言、经验与岗位差异。解释背景、说明依据、核对理解，是共同认识形成的具体过程。']),
s('让统一行动容得下自主性',['决定之前需要让不同判断有机会进入；决定之后可以按约行动，同时保留反馈与异常纠偏。意见未被采用，不应自动等于对共同事业不忠。','共同创造的组织机制，体现在沟通、协商、激励、制度与学习之中。共同意愿有方向意义，却不能自动消除现实分歧或代替实际配合。'])],questions:[
['所有人都同意，是否才算真正协同？',['不必。可以理解共同决定的理由、承担自己的任务，同时保留不同判断和回看条件。强求思想完全一致，反而可能使重要信息消失。','但分歧也不能成为暗中破坏约定的理由。需要清楚区分继续讨论、申请调整与已经承诺的行动。']],
['贡献不一样，如何讨论公平？',['先让风险、成本与不显眼的维护工作被看见，再讨论回报、资源和发展机会。公平不必等于每次分配完全相同，但应当能够说明理由并允许质疑。','不存在一劳永逸的计算。可讨论、可复核、可调整的过程，使差异有机会被持续处理。']],
['有些人总搭便车，怎么办？',['区分能力不足、任务模糊、资源缺失与有意不履约。先把责任和条件说清，再按约处理反复出现的问题。','合作需要信任，也需要边界。不能要求认真承担的人无限吸收他人的成本，来证明大家有共同意识。']]
],practice:['沿最终使用者的体验，检查一次跨岗位交接。','列出各方目标、所需信息、承担成本与未解决分歧。','约定一个共同结果、一个清楚接口和一种可执行的纠偏方式。'],case:['服务团队让承诺与交付共同面对使用者反馈；河谷城让上下游参与者说清各自风险与需求。协同从真实差异开始，而不是从宣布所有人利益一致开始。'],sources:['oldPowers','sethIndividual']},
evolve:{name:'进化',parent:'system',thesis:'让经验改变行动，也让系统有能力修改自己的规则。',question:'如果创始人没有看见问题，这个系统还能自行发现和修正吗？',definition:['进化，是通过反馈、试验、选择与学习，使系统的能力和规则持续回应环境与共同目的。它既包括改进做法，也包括重新检视评价尺度和权力安排。'],sections:[
s('经历只有进入下一次，才成为学习',['反复救火可能积累熟练，也可能只是积累疲惫。沉淀经验，要分清当时的信息、判断、行动与结果；选择有效做法，需要理解它为何有效、适用什么条件；放大之前，还要检验能否在别处成立。','沉淀、选择、放大，需要把反例与失败纳入学习，不只复制显眼的成功。']),
s('让规则也有可以被修改的规则',['需要明确谁能报告异常、提出改进，哪些受影响者参与讨论，谁有权决定试行，怎样评价代价，何时扩大或退出。更新不能永远等待创始人突然顿悟。','如果所有变化都由既得利益者单独审批，反馈可能永远触及不了关键处。独立复核与相称的监督，帮助系统看见自身不愿看见的部分。']),
s('稳定与更新，需要共同的节律',['可靠的合作和基本边界，为探索提供承载；有范围的试验，让结果有机会被辨认。所有规则同时变化，既增加负担，也使改进难以解释。','环境改变后，旧指标也应被检查。规模、速度或排名依旧上升，并不保证共同价值继续增长；减少不必要的活动同样可能是进化。'])],questions:[
['复盘怎样避免追责大会或互相安慰？',['先区分事实、当时可得信息与事后才知道的事情，再查明责任和条件。不能因结果不好就断言过程全错，也不能因动机良好就忽略损害。','复盘应形成具体改变：由谁调整什么、何时观察、怎样知道有效。问责与学习都要落到行动。']],
['怎样让权力交接不伤害持续性？',['提前形成继任能力，交清资料、权限、资源和未完成承诺，并结束模糊的双重指挥。继任者需要能够独立判断，而非只会复制旧领导者。','连续性来自使命、能力与可信关系，不要求每一项方法保持原样。']],
['系统很稳定，为什么还需要改革？',['稳定可能表示有效，也可能只是异常无法上报、外部代价长期不可见。要检查使用者、成员和环境的变化，而不只看内部指标。','同样，改革需要依据。能够被修改，不等于为了证明活力而不断改变。']]
],practice:['选择一个重复出现的问题，查明此前的复盘是否改变过实际条件。','安排一个有限试验，写清假设、观察信号、代价与退出标准。','检查提出修改者能否影响规则，而非只能获得“建议已收悉”。'],case:['服务组织定期修正扩张评价，并使新负责人有能力调整旧流程；河谷城把灾后发现纳入规则修订，使下一次改善不只依赖同一位负责人。'],sources:['oldPowers','ostrom']},
recognize:{name:'识人',parent:'people',thesis:'看见尚未显现的可能，也允许对方修正自己的判断。',question:'我认识的是这个人，还是我希望他成为的样子？',definition:['识人，是从实际表现、价值追求、内在动机、学习方式与承担意愿中持续理解一个人。它既看已经形成的能力，也看哪些条件能使新的能力显现。'],sections:[
s('标签描述过去，却容易决定未来的机会',['“只适合执行”“不够主动”可能来自真实经验，也可能反映任务模糊、资源不足或意见曾被否定。如果标签决定此后全部机会，最初判断就会被自己制造的条件不断验证。','识人需要改变一个条件，观察不同处境中的表现，也邀请本人说明愿望和经历。评价应当可修正，而不是一次看穿终身。']),
s('动机、气度与容量，回到可观察的行为',['欲、气、器，可以通过三个问题来观察：他珍视什么，压力与分歧中怎样对待人，能否理解更广泛和更长远的影响。不要把印象当成不可检验的本质。','关注具体事实：是否承认未知、怎样处理失败、是否能听见不同视角。对方愿不愿承担某种责任，也必须由对方参与回答。']),
s('潜能需要机会，也需要相称的检验',['提出一个有依据的发展假设，给出边界清楚的小型任务和必要支持，再共同回看。这样既不因当前不熟练而过早否定，也不把领导者的期待当成已经具备的能力。','识人不等于自认比本人更了解他是谁。提出可能是帮助，规定命运则越过了主体的边界。'])],questions:[
['怎样区别看见潜能与投射期待？',['潜能判断需要具体表现，也需要本人意愿和后续经验的支持。如果只有领导者热切想象，对方却不能拒绝，这更接近替他安排人生。','把判断保持为可以讨论的假设，让试行结果同时修正双方认识。']],
['有才但不断伤害合作，是否应该容忍？',['长处值得看见，但伤害不能因才华而自动免责。应明确职责边界，讨论可以发展的部分与不能继续发生的行为。','有些短处可以互补，有些直接影响关键责任，需要本人改变或调整位置。']],
['怎样避免只识别与自己相似的人？',['使用多种任务、多个观察者和明确的依据，检视机会是否只给了熟悉的表达方式。安静、不同文化或不同经历，不等于缺乏潜力。','识人的质量还取决于你是否愿意让一个不符合既有想象的人，用实际贡献改变你的理解。']]
],practice:['写下对一位合作者的一个标签，以及支撑它的具体事实。','询问他的兴趣、想承担的任务与所需支持。','安排一次有限而真实的尝试，让结果有机会修正标签。'],case:['提出质疑的同事可能具有原先未被看到的判断力；居民也可能拥有专业模型遗漏的现场知识。识人从放下单一权威视角开始。'],sources:['oldPowers']},
entrust:{name:'用人',parent:'people',thesis:'任其所长，使责任与权限、资源和自主空间相称。',question:'我交出去的是一项任务，还是可以真正施展判断的位置？',definition:['用人，是在共同目标下匹配人的能力、意愿与职责，建立真实授权和支持，使不同主体能够发挥所长并承担相应后果。它包含相互选择，而不只是单方面配置。'],sections:[
s('位置合适，长处才有作用',['同一种能力在不同任务与关系中可能有不同效果。要理解真正需要的贡献，而不是先有一个人，再为他寻找证明重要的位置。','短处可以通过互补和学习处理，关键职责所需能力却不能假装已经具备。任用需要同时对本人、合作伙伴与受影响者负责。']),
s('责任若没有权力，就容易成为替别人背负后果',['明确目标、可决定范围、必须遵守的边界、可用资源与需要共同讨论的情况。承担者应获得足够信息，而不必每一步都猜测领导者的意思。','授权也应配有支持和回看。初次承担者可能需要近距离反馈，成熟者则需要更完整空间；风险高低也影响检查程度。']),
s('让评价从服从方式转向判断与贡献',['如果目标与边界成立，不同的方法和风格可以被允许。若确有问题，应讨论证据、依据与实际影响，而不是仅要求回到领导者习惯。','成果分享、发展机会与风险分担，也体现共同事业如何对待参与者。只交工作不给成长，或只给头衔不给权限，难以形成真正的承担。'])],questions:[
['授权后做得和我不同怎么办？',['先判断差异是否影响共同目标、边界和其他人的工作。若只是偏好不同，可以把它视为另一种可学习的路径。','必要调整应说明理由与影响。没有真实差异的空间，授权就只剩委托执行。']],
['授权失败，应该全部收回来吗？',['先区分能力、信息、资源与责任意识的问题。可以缩小范围、增加支持或调整岗位，而不必从一次失误推断任何放手都不可靠。','严重越界需要按规则处理，但临时接管也应说明期限和后续安排，避免永久回到一人中心。']],
['共同事业的利益与个人志向不一致怎么办？',['承认差异，讨论职责要求与可能调整，不能把所有个人愿望都说成不顾大局。也不能要求组织无条件提供每一种成长路径。','当无法形成合适合作，清楚而负责的分离可能比勉强忠诚更好。']]
],practice:['检查一项已授权任务：承担者是否有足够信息、资源和决定权。','说明正常自主范围与异常求助信号，商定回看方式。','评价一次不同于自己风格的做法，区分偏好差异与真实风险。'],case:['创始人让新负责人调整交付方式，并按共同标准回看，而非逐步审批其全部动作；河谷城的不同执行主体则需清楚的公共权限与责任，不能仅靠私人信任。'],sources:['oldPowers']},
empower:{name:'成就',parent:'people',thesis:'成其才，成其志，成其人；把经验交出去，把成为谁的选择留给他。',question:'当他不再依赖我，甚至选择不同于我的道路，我能否仍看见他的成长？',definition:['成就，是支持他人逐渐形成独立求真、自主选择、面对失败、承担现实和创造生活的能力。它接续识人与用人，又超出当前任务的完成，关切一个主体怎样获得继续发展的力量。'],sections:[
s('成其才：让能力接触真实问题',['示范、练习与反馈使人理解不仅怎样做，也为什么这样做、在什么情况下需要改变。能力需要具体任务，而不只是被评价为有潜力。','错误应在可承担的范围内成为学习材料。把人推入缺少支持的困境，不是磨炼；替他消除所有后果，也难以形成判断。']),
s('成其志：让方向逐渐成为他自己的选择',['一个人可以起初借助别人的期待找到入口，也需要逐渐辨认自己真正重视什么。鼓励表达不同愿望，让选择与理由被认真讨论，使动力不只来自取悦权威。','帮助澄清志向，不等于必须赞同每个计划。可以说明风险与条件，但不以情感债务要求对方永远复制培养者的道路。']),
s('成其人：能够创造，也能够支持新的创造者',['主体性包含自主，也包含对事实、他人和后果的回应。敢表达还需要愿核实，能决定还需要会修复；失败并不取消价值，却会带来需要面对的现实。','当他开始形成自己的判断、帮助其他人成长，力量就出现新的中心。培养者从唯一答案的提供者，转为可以共同讨论的同行者。']),
s('真正的成就，容得下分离与超越',['他可以超过你，也可以不追求你看重的成就。离开原岗位不必否定共同经历，选择另一种生活也不等于没有出息。','已有承诺需要交接，合理边界需要遵守，但帮助不能成为永久占有其未来的依据。成就使成人最终通向无执与无敌。'])],questions:[
['为什么有些培养让人越来越不敢决定？',['如果每次自主判断都因为不符合领导偏好而受惩罚，人会把学习理解为猜测权威。掌握更多术语，也未必更有主体性。','给出真实选择，允许说明理由，并让诚实的修正获得空间。评价应该同时看结果、判断过程与责任。']],
['怎样帮助他面对失败，又不代替承担？',['先理解实际损失和需要，再区分哪些由他承担、哪些是支持条件不足或共同决定造成。协助修复、总结经验与安排下一次，不必把他整个人定义为失败。','支持不等于保证永远免于后果。它使后果可以被理解和处理，而不是成为对自身价值的终身判决。']],
['如果他不感激我，付出还有意义吗？',['关系中的感谢值得珍惜，但不应成为主体成长的入场条件。可以表达感受与期待，同时承认自己的帮助不产生对他人生的所有权。','若付出已经超出能够持续承担的范围，需要调整边界，而不是要求对方以服从偿还。']],
['怎样看见成就，而不只看职位与收入？',['看他能否独立核实信息，形成有根据的判断，承担承诺，面对不同意见与失败，并发展自己的生活。社会成果有意义，却不能替代这些能力。','也要允许成长有不同节律。成就不是培养者按时交出的作品，而是另一个主体持续参与的过程。']]
],practice:['与被支持者共同回看：能力、方向和自主承担分别发生了什么变化。','把一次直接给答案改成共同检查依据，让对方形成自己的决定。','安排一项减少依赖的交接，同时为必要求助保留清楚而有限的支持。'],case:['曾经依赖创始人的负责人，开始建立新的服务团队并培养自己的合作者；河谷城的居民不只接受安排，也能理解、质疑和参与公共生活。独立者的出现，是成人的成果。'],sources:['oldPowers','sethAuthority','xiyuZhuang']}
};
